// tabularUsage displays the usage of the tabular command and its subcommands.
func tabularUsage() {
	fmt.Fprintln(os.Stderr, "Service is the tabular service interface.")
	fmt.Fprintf(os.Stderr, "Usage:\n    %s [globalflags] tabular COMMAND [flags]\n\n", os.Args[0])
	fmt.Fprintln(os.Stderr, "COMMAND:")
	fmt.Fprintln(os.Stderr, "    list: List implements list.")
	fmt.Fprintln(os.Stderr, "    create: Create implements create.")
	fmt.Fprintln(os.Stderr, "    prompt: Prompt implements prompt.")
	fmt.Fprintln(os.Stderr, "    get: Get implements get.")
	fmt.Fprintln(os.Stderr, "    update: Update implements update.")
	fmt.Fprintln(os.Stderr, "    delete: Delete implements delete.")
	fmt.Fprintln(os.Stderr, "    clear-cells: ClearCells implements clear_cells.")
	fmt.Fprintln(os.Stderr, "    regenerate-cell: RegenerateCell implements regenerate_cell.")
	fmt.Fprintln(os.Stderr, "    generate: Generate implements generate.")
	fmt.Fprintln(os.Stderr)
	fmt.Fprintln(os.Stderr, "Additional help:")
	fmt.Fprintf(os.Stderr, "    %s tabular COMMAND --help\n", os.Args[0])
}
